def _sum(t):
    p = t.split("\n\n")[0]
    out = ""
    for s in p.replace("? ", "?|").replace(". ", ".|").split("|"):
        if out and len(out) + len(s) > 230: break
        out = (out + " " + s).strip()
    return out
TEXT = {k: [_sum(v), v] for k, v in TEXT.items()}
